def business_days(start, end, holidays=()):
    first = date.fromisoformat(start).toordinal()
    last = date.fromisoformat(end).toordinal()
    skip = {date.fromisoformat(h).toordinal() for h in holidays}
    return sum(1 for n in range(first, last) if (n + 6) % 7 < 5 and n not in skip)

from datetime import date, timedelta


def business_days(start, end, holidays=()):
    first = date.fromisoformat(start)
    last = date.fromisoformat(end)
    if last <= first:
        return 0
    holiday_set = {date.fromisoformat(h) for h in holidays}
    days = (first + timedelta(days=i) for i in range((last - first).days))
    return len([d for d in days if d.isoweekday() <= 5 and d not in holiday_set])
